{
  "book_code": "4BAR",
  "verses": [
    {
      "chapter": 5,
      "text_ar": "وقال له: \"إنها أورشليم.\"",
      "verse": 16
    },
    {
      "chapter": 5,
      "text_ar": "وقال له أبيمالك: \"أين إرميا الكاهن، وباروخ الكاتب، وكل شعب هذه المدينة، لأني لم أستطِع أن أجدَهم؟\"",
      "verse": 17
    },
    {
      "chapter": 5,
      "text_ar": "وقال له الشيخ: \"ألستَ من هذه المدينة، إذ تذكر اليوم إرميا وتُسأل عنه بعد هذا الوقت الطويل؟\"",
      "verse": 18
    },
    {
      "chapter": 5,
      "text_ar": "فإن إرميا في بابل مع الشعب، لأنهم سُبوا بواسطة الملك نبوخذناصر، وإرميا معهم ليبشرهم بالخير ويعلمهم الكلمة.",
      "verse": 19
    },
    {
      "chapter": 5,
      "text_ar": "وما إن سمع أبيمالك هذا الكلام من الشيخ حتى قال: \"لو لم تكن شيخاً، ولو كان مسموحاً لأحد أن يوبخ شخصاً طاعناً في السن، لضحكتُ عليك وقلتُ إنك فقدت صوابك، إذ تقول إن الشعب قد سُبي إلى بابل.\"",
      "verse": 20
    }
  ]
}
